const now = new Date();
const year = now.getFullYear();
const month = now.getMonth();

const startDate = new Date(year, month + 1, 1);
const endDate = new Date(year, month + 2, 0);

const formatDate = (d) => d.toISOString().split('T')[0];

const dates = [];
const cursor = new Date(startDate);
while (cursor <= endDate) {
  dates.push(formatDate(new Date(cursor)));
  cursor.setDate(cursor.getDate() + 1);
}

// Faith apparel Instagram competitors to scrape
const competitors = [
  'elevatedfaith',
  'walkinfaith_apparel',
  'godisdope',
  'crownsforchrist',
  'blessedco'
];

return [{
  json: {
    startDate: formatDate(startDate),
    endDate: formatDate(endDate),
    monthLabel: startDate.toLocaleString('default', { month: 'long', year: 'numeric' }),
    totalDays: dates.length,
    totalPosts: dates.length * 2,
    dates,
    competitors,
    planningTimestamp: new Date().toISOString()
  }
}];

const runData = $input.first().json;
const planningData = $('Set Planning Window').first().json;

return [{
  json: {
    ...planningData,
    apifyRunId: runData.data?.id || runData.id || null,
    apifyStatus: runData.data?.status || 'RUNNING'
  }
}];

const rawResults = $input.all();
const planningData = $('Store Run ID').first().json;

let allPosts = [];
for (const item of rawResults) {
  if (Array.isArray(item.json)) allPosts = allPosts.concat(item.json);
  else if (item.json && typeof item.json === 'object') allPosts.push(item.json);
}

const scoredPosts = allPosts
  .filter(p => (p.likesCount || p.likes || 0) > 100)
  .map(p => {
    const likes = p.likesCount || p.likes || 0;
    const comments = p.commentsCount || p.comments || 0;
    const caption = (p.caption || p.text || '').substring(0, 200);
    const handle = p.ownerUsername || p.username || 'unknown';
    return { handle, caption, likes, comments, hashtags: (p.hashtags || []).slice(0, 5).join(', ') };
  })
  .sort((a, b) => b.likes - a.likes);

const top20 = scoredPosts.slice(0, 20);

const topPostsSummary = top20.map((p, i) =>
  `${i + 1}. @${p.handle}: "${p.caption}" | ${p.likes.toLocaleString()} likes | Tags: ${p.hashtags}`
).join('\n');

return [{
  json: {
    ...planningData,
    topPostsSummary: topPostsSummary || 'No competitor data — use general faith apparel and lifestyle trends',
    totalPostsAnalyzed: allPosts.length,
    topEngagedPosts: top20.slice(0, 5).map(p => p.caption.substring(0, 100))
  }
}];

const competitorData = $('Analyze Competitor Data').first().json;

// Faith lifestyle apparel trend context (evergreen + seasonal)
const faithTrends = [
  'Spring collection drops — light fabrics, pastel faith graphics',
  'Easter/Resurrection Sunday outfits — high search volume',
  'OOTD reels with scripture overlays performing well',
  'Behind-the-scenes small business content driving community',
  'Matching sets with faith messages trending on TikTok',
  'Customer testimony posts — authentic UGC driving conversions',
  'Limited edition drops creating urgency and FOMO',
  'Everyday faith wear — normalizing faith in casual styling'
];

const month = new Date().getMonth();
const seasonalContext = month >= 2 && month <= 4 ? 'Spring/Easter season — emphasize renewal, fresh starts, resurrection themes' :
  month >= 5 && month <= 7 ? 'Summer season — outdoor events, vacations, beach faith wear' :
  month >= 8 && month <= 10 ? 'Fall season — back to school, harvest, gratitude themes' :
  'Holiday season — Christmas, gift giving, family gatherings';

return [{
  json: {
    ...competitorData,
    trendingTopics: faithTrends.join('\n'),
    seasonalContext
  }
}];

const geminiOutput = $input.first().json;
const planningData = $('Aggregate Trend Data').first().json;

let responseText = '';
if (typeof geminiOutput === 'string') responseText = geminiOutput;
else if (geminiOutput.response) responseText = String(geminiOutput.response);
else if (geminiOutput.text) responseText = String(geminiOutput.text);
else if (geminiOutput.content) responseText = String(geminiOutput.content);
else if (geminiOutput.output) responseText = String(geminiOutput.output);
else responseText = JSON.stringify(geminiOutput);

let calendar;
try {
  let jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/```\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/(\[[\s\S]*\])/);
  const jsonString = jsonMatch ? jsonMatch[1].trim() : responseText.trim();
  calendar = JSON.parse(jsonString);
  if (!Array.isArray(calendar)) throw new Error('Not an array');
} catch (e) {
  calendar = planningData.dates.flatMap(date => [
    { date, slot: 'morning', pillar: 'Pillar 2 - Faith + Fashion', title: 'Faith Style Inspiration ' + date, content_brief: 'Share how faith and fashion intersect for the modern woman.', video_format: 'Reel 30-60s', trending_angle: 'Faith lifestyle' },
    { date, slot: 'evening', pillar: 'Pillar 1 - Product Showcase', title: 'Product Feature ' + date, content_brief: 'Showcase a Dorothy Dean Designs piece with styling tips.', video_format: 'Single Image', trending_angle: 'Fashion OOTD' }
  ]);
}

const enrichedCalendar = calendar.map((post, idx) => ({
  ...post,
  post_index: idx + 1,
  month_label: planningData.monthLabel,
  brand: 'Dorothy Dean Designs',
  status: 'Generate Content',
  created_by: 'DD Monthly Planner'
}));

return enrichedCalendar.map(post => ({ json: post }));
